<?php namespace App\Filament\Resources\UpbringingEventResource\RelationManagers;use Filament\Forms;use Filament\Resources\Form;use Filament\Resources\RelationManagers\RelationManager;use Filament\Resources\Table;use Filament\Tables;use Illuminate\Support\Facades\DB;class ParticipantsRelationManager extends RelationManager{protected static string $relationship='participants';protected static ?string $recordTitleAttribute='student_id';protected static ?string $title='Участники';public static function form(Form $f):Form{return $f->schema([Forms\Components\Select::make('student_id')->label('Студент')->options(fn()=>DB::table('students')->where('status','active')->orderBy('last_name')->get()->mapWithKeys(fn($s)=>[$s->id=>trim($s->last_name.' '.$s->first_name)]))->searchable()->required(),Forms\Components\TextInput::make('role')->label('Роль')->default('participant')->required(),Forms\Components\Toggle::make('attended')->label('Участвовал')->default(true)]);}public static function table(Table $t):Table{return $t->columns([Tables\Columns\TextColumn::make('student_id')->label('Студент')->formatStateUsing(fn($s)=>($x=DB::table('students')->where('id',$s)->first())?trim($x->last_name.' '.$x->first_name):'—'),Tables\Columns\TextColumn::make('role')->label('Роль'),Tables\Columns\IconColumn::make('attended')->label('Участие')->boolean()])->headerActions([Tables\Actions\CreateAction::make()->label('Добавить участника')])->actions([Tables\Actions\EditAction::make(),Tables\Actions\DeleteAction::make()]);}}